	private const int CAMERA_2D_MIN_X = 100;
	private const int CAMERA_2D_MIN_Y = 100;
	private const int CAMERA_2D_MAX_X = 1180;
	private const int CAMERA_2D_MAX_Y = 620;
	private static float eventTime;
	public static int TrainerSearch() {
        if (PlayerWork.BtlSearcherCharge < 100)
            return 1;

        EvDataManager evDataManager = EvDataManager.Instanse;
        Vector2Int playerPos = EntityManager.activeFieldPlayer.gridPosition;
        // FieldCamera.GetCamera (flag-less, b265) inlined as the raw +0x20 read @01781cbc.
        Camera camera = GameManager.fieldCamera.GetCamera();
        int result = 2;

        for (int i = 0; i < evDataManager.FieldObjectMoveCodes.Count; i++)
        {
            FieldObjectEntity entity = evDataManager.FieldObjectMoveCodes[i].Entity;
            if (entity.EventParams.TrainerID == TrainerID.NONE)
                continue;

            if (!entity.gameObject.activeInHierarchy)
                continue;

            // X through UnityEngine.Mathf.Abs (a call), Y through an inlined System.Math.Abs (cneg @01781e2c).
            int distX = Mathf.Abs(playerPos.x - entity.gridPosition.x);
            int distY = Math.Abs(playerPos.y - entity.gridPosition.y);
            if (distX > RANGE_X || distY > RANGE_UY)
                continue;

            // b.gt / b.mi (@01781e8c..01781ebc): a NaN coordinate is NOT rejected.
            Vector2 screenPos = RectTransformUtility.WorldToScreenPoint(camera, entity.worldPosition);
            if (screenPos.y > CAMERA_2D_MAX_Y || screenPos.x > CAMERA_2D_MAX_X || screenPos.x < CAMERA_2D_MIN_X || screenPos.y < CAMERA_2D_MIN_Y)
                continue;

            if (result == 2)
                result = 3;

            if (TrainerWork.GetWinFlag(entity.EventParams.TrainerID))
