                    evDataManager.FieldObjectMoveCodes[i].MVCodeChange(FieldObjectMoveCode.MV_RND_LR);
                }

                TrainerWork.RematchTrainerID(entity.EventParams.TrainerID);
                FieldCanvas.SetBalloon(1, entity.transform);
                TrainerWork.SetBattleSaercher(entity.EventParams.TrainerID);
